            /// <summary>
            /// MPJ_12065_RestrictCostchangesOnPOs by chaminda on 14022022
            /// </summary>
            /// <param name = "_formReferenceControl"> Get Form reference control</param>
            /// <returns>ret</returns>
            public Common resolveReference(FormReferenceControl _formReferenceControl)
            {
                Common ret;
                EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;
                EcoResCategoryHierarchy     categoryHierarchy  = EcoResCategoryHierarchy::find(METPOCostUpdateExceptionRules.CategoryHierarchy);

                select firstonly ecoResCategoryHierarchyRole
                    where ecoResCategoryHierarchyRole.CategoryHierarchy == categoryHierarchy.RecId;
                
                ret = EcoResCategory::lookupCategoryHierarchy(_formReferenceControl,categoryHierarchy);
                
            
                return ret;
            }

